import { useEffect, useState } from 'react';
import { analyzeSentiment, generateRecipes, getThinkingText, type Stock } from '../../services/ai';
import type { Flavor, Mood, Recipe } from '../../types';
import GeneratedArt from '../../components/GeneratedArt';
import { SelectionChips } from './Selector';

interface Props {
  flavor1: Flavor;
  flavor2: Flavor;
  mood: Mood;
  stock: Stock;
  onDone: (recipes: Recipe[]) => void;
}

const CHARS_PER_TICK = 3;
const TICK_MS = 20;
const CARD_REVEAL_MS = 600;

/** Streams the (mock) model's reasoning and reveals recipe cards as they "arrive". */
export default function Mixing({ flavor1, flavor2, mood, stock, onDone }: Props) {
  const [fullText, setFullText] = useState('');
  const [shown, setShown] = useState(0);
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [revealed, setRevealed] = useState(0);

  useEffect(() => {
    let cancelled = false;
    const timers: number[] = [];
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    (async () => {
      const s = await analyzeSentiment(mood);
      if (cancelled) return;
      const text = getThinkingText(flavor1, flavor2, mood, s);
      setFullText(text);

      if (reduceMotion) {
        setShown(text.length);
      } else {
        // Derive progress from elapsed time so throttled background timers don't stall the stream.
        const start = performance.now();
        const id = window.setInterval(() => {
          const n = Math.min(Math.floor(((performance.now() - start) / TICK_MS) * CHARS_PER_TICK), text.length);
          if (n >= text.length) window.clearInterval(id);
          setShown(n);
        }, TICK_MS);
        timers.push(id);
      }

      const r = await generateRecipes(flavor1, flavor2, mood, stock);
      if (cancelled) return;
      setRecipes(r);
      const revealId = window.setInterval(() => {
        setRevealed((n) => {
          if (n + 1 >= r.length) window.clearInterval(revealId);
          return Math.min(n + 1, r.length);
        });
      }, reduceMotion ? 0 : CARD_REVEAL_MS);
      timers.push(revealId);
    })();

    return () => {
      cancelled = true;
      timers.forEach((t) => window.clearInterval(t));
    };
  }, [flavor1, flavor2, mood, stock]);

  const streaming = fullText.length === 0 || shown < fullText.length;
  const done = !streaming && recipes.length > 0 && revealed === recipes.length;

  return (
    <section className="mixing" aria-labelledby="mixing-heading">
      <div className="card mixing__panel">
        <div className="mixing__head">
          <h1 id="mixing-heading">Mixing your recipe</h1>
        </div>
        <SelectionChips flavors={[flavor1, flavor2]} mood={mood} />
        <p className="mixing__stream" aria-live="off">
          {fullText ? fullText.slice(0, shown) : 'Generating..'}
          {streaming && <span className="caret" aria-hidden="true" />}
        </p>
        <p className="mixing__status" role="status">
          {done ? `${recipes.length} recipes ready!` : 'creating recipes...'}
        </p>
      </div>

      <div className="card mixing__tray">
        {recipes.length === 0 ? (
          <div className="mixing__shimmer" aria-hidden="true" />
        ) : (
          <ul className="recipe-strip">
            {recipes.slice(0, revealed).map((r) => (
              <li key={r.id} className="recipe-mini">
                <div className="recipe-mini__art">
                  <GeneratedArt recipe={r} />
                </div>
                <div className="recipe-mini__body">
                  <h2>{r.name}</h2>
                  <p>{r.description}</p>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="nav-buttons">
        <button type="button" className="btn btn--primary" disabled={!done} onClick={() => onDone(recipes)}>
          Pick your recipe <span aria-hidden="true">→</span>
        </button>
      </div>
    </section>
  );
}
